import{_ as i,a as n,b as o,c as a}from"./chunks/m_prilohy_menu.BEI7bXma.js";import{_ as e,a as s}from"./chunks/m_edit_fotky3.Tj88u-hW.js";import{_ as r}from"./chunks/m_edit_fotky2.IVXZ5228.js";import{_ as c,o as h,c as d,aa as l}from"./chunks/framework.BAs_AphD.js";const g="/buildary-help-preview/media/cs/tickets/m_vyjadreniano.png",p="/buildary-help-preview/media/cs/tickets/m_vyjadrenine.png",m="/buildary-help-preview/media/cs/tickets/m_edit_prilohy.png",S=JSON.parse('{"title":"Edit Ticket","description":"","frontmatter":{"title":"Edit Ticket","wiki":"en:tickets:m_task_edit"},"headers":[],"relativePath":"en/tickets/m_task_edit.md","filePath":"en/tickets/m_task_edit.md","lastUpdated":1794388980000}'),u={name:"en/tickets/m_task_edit.md"};function f(b,t,k,w,_,y){return h(),d("div",null,[...t[0]||(t[0]=[l('<h1 id="edit-ticket" tabindex="-1">Edit Ticket <a class="header-anchor" href="#edit-ticket" aria-label="Permalink to &quot;Edit Ticket&quot;">​</a></h1><figure class="shot" style="--w:270px;"><img src="'+i+'" alt="Ticket Details / Edit Ticket" width="250" loading="lazy"></figure><p><strong>Edit Ticket</strong> is accessible from the Ticket List by tapping the ticket Subject field. This opens the Ticket Details form.</p><p>Users can only edit information allowed by their permissions.</p><p>Permissions for ticket participants are set as follows:</p><ul><li><strong>Ticket Author</strong> → has the fewest restrictions and can essentially edit everything, including the ability to delete the ticket.</li><li><strong>Approver</strong> → can edit the status and labels, add attachments, edit drawings and the map, change participants, and add Statements.</li><li><strong>Assignee</strong> → can edit only the status and labels and add Statements. Other data is available for viewing or downloading (attachments).</li></ul><p>Permissions resulting from the user&#39;s assigned role on the project primarily determine which tickets the user is allowed to see and which restrictions apply.</p><p>The exception is the <strong>Administrator</strong> role. This role allows the user to edit everything except participating in the Discussion. However, if the Administrator is also a ticket participant in any capacity (Author / Assignee / Approver), they can participate in the Discussion.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The actual start / end date can never be edited. These dates are automatically filled in by the application based on the actual progress.</p></div><p>In the bottom icon bar, there is an icon for <strong>accessing the Statement for the ticket</strong>. If there is an <strong>orange dot</strong> next to it, this means that the <strong>Statement contains one or more records</strong>. An icon without a dot indicates that it contains no records:</p><figure class="shot" style="--w:270px;"><img src="'+g+'" alt="Ticket with Records in the Statement" width="250" loading="lazy"></figure><img src="'+p+'" alt="Ticket without Records in the Statement" width="250" loading="lazy"><p>Tapping this icon opens the Statement. If the user has the required permission, they can add a record, as described below.</p><h2 id="statement-for-the-ticket" tabindex="-1">Statement for the Ticket <a class="header-anchor" href="#statement-for-the-ticket" aria-label="Permalink to &quot;Statement for the Ticket&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+n+'" alt="Statement - Record with Photos" width="250" loading="lazy"></figure><figure class="shot" style="--w:270px;"><img src="'+o+'" alt="Statement - Adding Records" width="250" loading="lazy"></figure><p>All ticket participants can participate in the Statement. New threads can be created and responses can be added to existing threads.</p><p>To create a <strong>new thread</strong>, the user taps the <strong>+</strong> icon in the bottom icon bar.</p><p>To add a <strong>response</strong>, the user taps the Respond icon in the bottom-right corner of the post they want to respond to. The response is then added below the original post.</p><p><strong>Attachments</strong> can be added to records. The new record window has a bottom icon bar that allows the user to use the <strong>camera to take an immediate photo</strong> for the record or the <strong>device storage to select the relevant file</strong>.</p><p>The <strong>author of a record can edit or delete their record</strong>, but only <strong>until someone responds to it</strong>. Once a response is added, editing and deletion are locked.</p><h2 id="attachment-editing" tabindex="-1">Attachment Editing <a class="header-anchor" href="#attachment-editing" aria-label="Permalink to &quot;Attachment Editing&quot;">​</a></h2><figure class="shot" style="--w:270px;"><img src="'+a+'" alt="Attachment Menu" width="250" loading="lazy"></figure><p>In the top-right corner of each attachment, there is a <strong>vertical Three-Dot Menu</strong>. Tapping it opens the <strong>attachment menu</strong> available according to the user&#39;s permissions:</p><p><strong>Share</strong> is the only option <strong>available to everyone</strong>. This option displays the apps available on the device for sharing, allowing the user to share the individual attachment with their contacts.</p><p>Only the <strong>author</strong> of the attachment can <strong>Delete</strong> it.</p><p><strong>Edit</strong> is available <strong>only for image attachments</strong> and is also available only to their <strong>author</strong>. This option moves the image into editing mode, as described below.</p><h3 id="editing-an-image-attachment" tabindex="-1">Editing an Image Attachment <a class="header-anchor" href="#editing-an-image-attachment" aria-label="Permalink to &quot;Editing an Image Attachment&quot;">​</a></h3><figure class="shot" style="--w:270px;"><img src="'+m+'" alt="Editing an Attachment" width="250" loading="lazy"></figure><p>Editing is performed using the functions in the <strong>editing toolbar below the photo</strong>. Available functions include:</p><ul><li>various cropping modes, rotation, and mirroring</li><li>inserting shapes, curves, arrows, etc., including options for line color and thickness</li><li>inserting text, including options for color, font, etc.</li><li>pen mode, including options for line color and thickness</li><li>adjusting photo properties such as brightness, contrast, sharpness, etc.</li></ul><p><strong>Saving the changes and returning to the ticket</strong> is done by tapping the confirmation icon <img src="'+e+'" alt="Confirm" width="45" data-no-zoom loading="lazy"> in the bottom-right corner.</p><p>To return to the ticket <strong>without saving the changes</strong>, tap the <strong>back arrow in the top blue bar of the screen</strong>.</p><figure class="shot" style="--w:270px;"><img src="'+r+'" alt="Editing Functions" width="250" loading="lazy"></figure><figure class="shot" style="--w:270px;"><img src="'+s+'" alt="Restore Previous Version" width="250" loading="lazy"></figure><p>After selecting an editing function, its options open in an expanded menu in the associated toolbar below the image.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>After using EACH selected function, the user must <strong>confirm the change using the checkmark above the photo</strong>, and only then <strong>return to the editing options using the back arrow BELOW the image</strong>. If the user does not confirm the change and returns to the editing options, the change will not be saved.</p></div><p>During editing, the author can <strong>return to previous steps using the arrows above the image</strong>, or <strong>restore the original version before editing</strong> using the icon above the image on the right → after using it, <strong>all changes to the image are deleted and the edited version cannot be restored</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Saving the changes and returning to the ticket</strong> is done by tapping the confirmation icon <img src="'+e+'" alt="Confirm" width="45" data-no-zoom loading="lazy"> in the bottom-right corner.</p></div>',39)])])}const E=c(u,[["render",f]]);export{S as __pageData,E as default};
